// Fiktive Beispielanlage: Förderer / Drehtisch (SCRUM-41)
const assembly = {
  anlage: "Foerderer_Drehtisch_v1",
  format_quelle: "STEP (ISO 10303-21) – fiktiv",
  komponenten: [
    { id: "K001", name: "Hauptrahmen", typ: "Tragstruktur", material: "Stahl", bbox: { x: 2000, y: 800, z: 600 }, kinder: ["K002","K003","K004"] },
    { id: "K002", name: "Foerderband_Links", typ: "Foerdertechnik", material: "Gummi/Stahl", bbox: { x: 1800, y: 200, z: 100 }, kinder: [] },
    { id: "K003", name: "Foerderband_Rechts", typ: "Foerdertechnik", material: "Gummi/Stahl", bbox: { x: 1800, y: 200, z: 100 }, kinder: [] },
    { id: "K004", name: "Drehtisch_Zentrum", typ: "Drehtisch", material: "Stahl", bbox: { x: 600, y: 600, z: 200 }, kinder: ["K005","K006"] },
    { id: "K005", name: "Antriebsmotor_Drehtisch", typ: "Antrieb", material: "Metall", bbox: { x: 200, y: 200, z: 300 }, kinder: [] },
    { id: "K006", name: "Sensor_Endlage", typ: "Sensor", material: "Kunststoff/Metall", bbox: { x: 50, y: 50, z: 80 }, kinder: [] }
  ],
  sps_variablen_bekannt: true,
  kinematik_vorhanden: false
};

return [{ json: { assembly, assembly_json: JSON.stringify(assembly, null, 2) } }];

// Tag A: Function-Call extrahieren (Gemini), Rolle setzen
const r = $json;
let payload;
try {
  const parts = r.candidates?.[0]?.content?.parts || [];
  const fc = parts.find(p => p.functionCall);
  if (fc) {
    payload = fc.functionCall.args;
  } else if (parts.find(p => p.text)) {
    payload = { _raw_text: parts.map(p => p.text || '').join('') };
  } else {
    payload = { _error: 'Unbekanntes Response-Format', _raw: r };
  }
} catch (e) {
  payload = { _error: e.message, _raw: r };
}
return [{ json: { rolle: 'klassifikation', payload, tokens_in: r.usageMetadata?.promptTokenCount ?? null, tokens_out: r.usageMetadata?.candidatesTokenCount ?? null } }];

// Tag B: Function-Call extrahieren (Gemini), Rolle setzen
const r = $json;
let payload;
try {
  const parts = r.candidates?.[0]?.content?.parts || [];
  const fc = parts.find(p => p.functionCall);
  if (fc) {
    payload = fc.functionCall.args;
  } else if (parts.find(p => p.text)) {
