  }
} catch (e) {
  payload = { _error: e.message, _raw: r };
}
return [{ json: { rolle: 'importformat', payload, tokens_in: r.usageMetadata?.promptTokenCount ?? null, tokens_out: r.usageMetadata?.candidatesTokenCount ?? null } }];

// Tag C: Function-Call extrahieren (Gemini), Rolle setzen
const r = $json;
let payload;
try {
  const parts = r.candidates?.[0]?.content?.parts || [];
  const fc = parts.find(p => p.functionCall);
  if (fc) {
    payload = fc.functionCall.args;
  } else if (parts.find(p => p.text)) {
    payload = { _raw_text: parts.map(p => p.text || '').join('') };
  } else {
    payload = { _error: 'Unbekanntes Response-Format', _raw: r };
  }
} catch (e) {
  payload = { _error: e.message, _raw: r };
}
return [{ json: { rolle: 'simulationslogik', payload, tokens_in: r.usageMetadata?.promptTokenCount ?? null, tokens_out: r.usageMetadata?.candidatesTokenCount ?? null } }];

// Per Tag mappen statt per Position. Robust gegen Reihenfolge.
const items = $input.all().map(i => i.json);
const byRolle = (r) => items.find(i => i.rolle === r) || { payload: { _error: 'Rolle ' + r + ' fehlt' }, tokens_in: 0, tokens_out: 0 };

const k = byRolle('klassifikation');
const f = byRolle('importformat');
const s = byRolle('simulationslogik');

const tokens_total = items.reduce((sum, i) => sum + (i.tokens_in || 0) + (i.tokens_out || 0), 0);

return [{
  json: {
    klassifikation_json: JSON.stringify(k.payload, null, 2),
    importformat_json: JSON.stringify(f.payload, null, 2),
    simulationslogik_json: JSON.stringify(s.payload, null, 2),
    klassifikation_obj: k.payload,
    importformat_obj: f.payload,
    simulationslogik_obj: s.payload,
    tokens_agenten: tokens_total,
    anlage: 'Foerderer_Drehtisch_v1',
    datum: new Date().toISOString().split('T')[0]
  }
}];

// Bericht extrahieren (Gemini), Markdown + Meta auf Disk persistieren
const fs = require('fs');
const path = require('path');

const response = $json;
let bericht = '';
let usage = {};
try {
  const parts = response.candidates[0].content.parts || [];
  bericht = parts.map(p => p.text || '').join('');
  usage = response.usageMetadata || {};
} catch (e) {
  bericht = '[FEHLER beim Bericht-Extrakt: ' + e.message + ']\n\nRoh-Response:\n' + JSON.stringify(response, null, 2);
}

const now = new Date();
const ts = now.toISOString().replace(/[:.]/g, '-').replace(/T/, '_').slice(0, 19);
const dir = '/Users/stm/Desktop/UNI/Master/1. Semester/06_Project_ZOLLERN/sprints/sprint-1/SCRUM-40/runs_gemini';
fs.mkdirSync(dir, { recursive: true });

const mdPath = path.join(dir, ts + '.md');
const metaPath = path.join(dir, ts + '.meta.json');

fs.writeFileSync(mdPath, bericht);

const meta = {
  timestamp: now.toISOString(),
  modell: 'gemini-2.5-flash',
  anlage: 'Foerderer_Drehtisch_v1',
  tokens_summary: { input: usage.promptTokenCount || 0, output: usage.candidatesTokenCount || 0 },
  pfad_bericht: mdPath
};
fs.writeFileSync(metaPath, JSON.stringify(meta, null, 2));

console.log('=== ZOLLERN BERICHT (Gemini) ===');
console.log('Geschrieben: ' + mdPath);
console.log(bericht);

return [{ json: { bericht, status: 'persisted', pfad: mdPath, meta_pfad: metaPath, ...meta } }];

// Plan aus Function-Call extrahieren (Gemini)
const response = $json;
let plan = null;
let tokens = { in: 0, out: 0 };
try {
  const parts = response.candidates?.[0]?.content?.parts || [];
  const fc = parts.find(p => p.functionCall);
  plan = fc ? fc.functionCall.args : null;
  tokens.in = response.usageMetadata?.promptTokenCount || 0;
  tokens.out = response.usageMetadata?.candidatesTokenCount || 0;
} catch (e) {
  return [{ json: { error: 'Plan-Extraktion fehlgeschlagen: ' + e.message, raw: response } }];
}
if (!plan) return [{ json: { error: 'Kein Function-Call im Response', raw: response } }];

return [{
  json: {
    plan,
    plan_json: JSON.stringify(plan, null, 2),
    tokens_plan: tokens,
    rolle: 'plan'
  }
}];

// FIX Bug 2: Plan mit Rolle 'plan' in Merge einspeisen
// Damit Logic Builder + Sammle alle Calls den Plan via Aggregate finden
return [{
  json: {
    rolle: 'plan',
    plan: $json.plan,
    plan_json: $json.plan_json,
    tokens_plan: $json.tokens_plan
  }
}];

